{
  "understanding": {
    "purpose": "A reference table for comparing checkout interface strings across four languages by translation key.",
    "reading": "Readers locate a key in the first column, then scan across the row to compare its translations; consistent row alignment helps keep those values associated.",
    "groups": [
      "English, 中文, 日本語, and العربية are parallel translations of the same string and should remain easy to compare across each row.",
      "Key is the row identifier and needs enough width to distinguish entries without breaking them."
    ],
    "keep_intact": [
      "Translation keys, including their dots and underscores.",
      "Individual words and meaningful number ranges such as 3–5 where possible."
    ],
    "may_wrap": [
      "Longer English and Arabic phrases can wrap at word boundaries.",
      "Chinese and Japanese text can wrap naturally between characters.",
      "Short translations can use the height created by longer translations in the same row."
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [227, 115, 100, 120, 99],
      "idea": "Keep keys intact and distribute the remaining space relatively evenly among translations, with extra room for the longer Japanese strings."
    },
    {
      "name": "B",
      "widths": [227, 140, 85, 125, 84],
      "idea": "Give English more room for word-based wrapping while relying on flexible character wrapping in Chinese and Japanese."
    },
    {
      "name": "C",
      "widths": [227, 100, 82, 155, 97],
      "idea": "Prioritize the longest Japanese translation, allowing English and Chinese to wrap more often while retaining room for Arabic words."
    }
  ]
}
